-- Vantras EHS Academy production-oriented relational schema (PostgreSQL compatible concepts)
-- The runnable prototype automatically creates its compact SQLite schema.

CREATE TABLE users (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, mobile VARCHAR(32), password_hash TEXT NOT NULL, status VARCHAR(32) DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE roles (id BIGSERIAL PRIMARY KEY, code VARCHAR(64) UNIQUE NOT NULL, name VARCHAR(120) NOT NULL);
CREATE TABLE permissions (id BIGSERIAL PRIMARY KEY, code VARCHAR(120) UNIQUE NOT NULL, name VARCHAR(180) NOT NULL);
CREATE TABLE user_roles (user_id BIGINT REFERENCES users(id), role_id BIGINT REFERENCES roles(id), PRIMARY KEY(user_id, role_id));
CREATE TABLE role_permissions (role_id BIGINT REFERENCES roles(id), permission_id BIGINT REFERENCES permissions(id), PRIMARY KEY(role_id, permission_id));
CREATE TABLE student_profiles (user_id BIGINT PRIMARY KEY REFERENCES users(id), qualification TEXT, designation TEXT, company TEXT, industry TEXT, experience_years NUMERIC(5,2));
CREATE TABLE trainer_profiles (user_id BIGINT PRIMARY KEY REFERENCES users(id), bio TEXT, specialities TEXT, verified BOOLEAN DEFAULT FALSE);
CREATE TABLE corporate_companies (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL, gst_no VARCHAR(32), status VARCHAR(32) DEFAULT 'active');
CREATE TABLE corporate_profiles (user_id BIGINT PRIMARY KEY REFERENCES users(id), company_id BIGINT REFERENCES corporate_companies(id));
CREATE TABLE categories (id BIGSERIAL PRIMARY KEY, name VARCHAR(160) UNIQUE NOT NULL, slug VARCHAR(180) UNIQUE NOT NULL);
CREATE TABLE courses (id BIGSERIAL PRIMARY KEY, code VARCHAR(80) UNIQUE NOT NULL, title VARCHAR(255) NOT NULL, category_id BIGINT REFERENCES categories(id), trainer_id BIGINT REFERENCES users(id), description TEXT, level VARCHAR(40), duration_minutes INTEGER, mode VARCHAR(40), language VARCHAR(40), price NUMERIC(12,2), status VARCHAR(32), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE course_modules (id BIGSERIAL PRIMARY KEY, course_id BIGINT REFERENCES courses(id), title VARCHAR(255) NOT NULL, sequence_no INTEGER NOT NULL);
CREATE TABLE lessons (id BIGSERIAL PRIMARY KEY, module_id BIGINT REFERENCES course_modules(id), title VARCHAR(255) NOT NULL, sequence_no INTEGER NOT NULL);
CREATE TABLE lesson_contents (id BIGSERIAL PRIMARY KEY, lesson_id BIGINT REFERENCES lessons(id), content_type VARCHAR(40), title VARCHAR(255), storage_key TEXT, external_url TEXT, sequence_no INTEGER NOT NULL);
CREATE TABLE enrollments (id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES users(id), course_id BIGINT REFERENCES courses(id), status VARCHAR(40), enrolled_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, completed_at TIMESTAMP, UNIQUE(user_id,course_id));
CREATE TABLE learning_progress (id BIGSERIAL PRIMARY KEY, enrollment_id BIGINT REFERENCES enrollments(id), lesson_id BIGINT REFERENCES lessons(id), completion_percent NUMERIC(5,2), completed_at TIMESTAMP, UNIQUE(enrollment_id,lesson_id));
CREATE TABLE video_progress (id BIGSERIAL PRIMARY KEY, enrollment_id BIGINT REFERENCES enrollments(id), content_id BIGINT REFERENCES lesson_contents(id), watched_seconds INTEGER, duration_seconds INTEGER, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE assessments (id BIGSERIAL PRIMARY KEY, course_id BIGINT REFERENCES courses(id), title VARCHAR(255), difficulty VARCHAR(32), time_minutes INTEGER, pass_percent NUMERIC(5,2), max_attempts INTEGER, active BOOLEAN DEFAULT TRUE);
CREATE TABLE questions (id BIGSERIAL PRIMARY KEY, assessment_id BIGINT REFERENCES assessments(id), question_text TEXT NOT NULL, question_type VARCHAR(40), difficulty VARCHAR(32), marks NUMERIC(8,2), negative_marks NUMERIC(8,2), explanation TEXT);
CREATE TABLE answers (id BIGSERIAL PRIMARY KEY, question_id BIGINT REFERENCES questions(id), answer_text TEXT NOT NULL, is_correct BOOLEAN DEFAULT FALSE);
CREATE TABLE assessment_attempts (id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES users(id), assessment_id BIGINT REFERENCES assessments(id), started_at TIMESTAMP, submitted_at TIMESTAMP, score NUMERIC(8,2), passed BOOLEAN);
CREATE TABLE assessment_results (id BIGSERIAL PRIMARY KEY, attempt_id BIGINT REFERENCES assessment_attempts(id), question_id BIGINT REFERENCES questions(id), answer_id BIGINT REFERENCES answers(id), is_correct BOOLEAN, marks_awarded NUMERIC(8,2));
CREATE TABLE assignments (id BIGSERIAL PRIMARY KEY, course_id BIGINT REFERENCES courses(id), title VARCHAR(255), instructions TEXT, due_at TIMESTAMP, max_marks NUMERIC(8,2));
CREATE TABLE assignment_submissions (id BIGSERIAL PRIMARY KEY, assignment_id BIGINT REFERENCES assignments(id), student_id BIGINT REFERENCES users(id), storage_key TEXT, status VARCHAR(40), marks NUMERIC(8,2), trainer_comments TEXT, submitted_at TIMESTAMP);
CREATE TABLE certificates (id BIGSERIAL PRIMARY KEY, certificate_no VARCHAR(120) UNIQUE NOT NULL, user_id BIGINT REFERENCES users(id), course_id BIGINT REFERENCES courses(id), issue_date DATE, completion_date DATE, status VARCHAR(32), qr_payload TEXT, pdf_storage_key TEXT);
CREATE TABLE certificate_verifications (id BIGSERIAL PRIMARY KEY, certificate_id BIGINT REFERENCES certificates(id), verified_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, source_ip VARCHAR(64));
CREATE TABLE orders (id BIGSERIAL PRIMARY KEY, order_no VARCHAR(120) UNIQUE, user_id BIGINT REFERENCES users(id), course_id BIGINT REFERENCES courses(id), amount NUMERIC(12,2), tax NUMERIC(12,2), discount NUMERIC(12,2), status VARCHAR(32), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE checkout_records (id BIGSERIAL PRIMARY KEY, checkout_id VARCHAR(120) UNIQUE NOT NULL, user_id BIGINT REFERENCES users(id), course_id BIGINT REFERENCES courses(id), billing_name VARCHAR(180) NOT NULL, billing_email VARCHAR(255) NOT NULL, billing_mobile VARCHAR(32), billing_country VARCHAR(80), payment_method VARCHAR(40), amount NUMERIC(12,2), status VARCHAR(32), order_id VARCHAR(120), payment_id VARCHAR(180), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payments (id BIGSERIAL PRIMARY KEY, order_id BIGINT REFERENCES orders(id), gateway VARCHAR(40), gateway_payment_id VARCHAR(180), method VARCHAR(40), amount NUMERIC(12,2), status VARCHAR(32), paid_at TIMESTAMP);
CREATE TABLE refunds (id BIGSERIAL PRIMARY KEY, payment_id BIGINT REFERENCES payments(id), amount NUMERIC(12,2), status VARCHAR(32), reason TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invoices (id BIGSERIAL PRIMARY KEY, order_id BIGINT REFERENCES orders(id), invoice_no VARCHAR(120) UNIQUE, taxable_amount NUMERIC(12,2), gst NUMERIC(12,2), total NUMERIC(12,2), pdf_storage_key TEXT, issued_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE coupons (id BIGSERIAL PRIMARY KEY, code VARCHAR(80) UNIQUE, discount_type VARCHAR(24), value NUMERIC(12,2), expires_at TIMESTAMP, usage_limit INTEGER, active BOOLEAN DEFAULT TRUE);
CREATE TABLE corporate_employees (id BIGSERIAL PRIMARY KEY, company_id BIGINT REFERENCES corporate_companies(id), employee_code VARCHAR(80), name VARCHAR(180), email VARCHAR(255), department VARCHAR(160), designation VARCHAR(160), location VARCHAR(160), UNIQUE(company_id,employee_code));
CREATE TABLE corporate_enrollments (id BIGSERIAL PRIMARY KEY, employee_id BIGINT REFERENCES corporate_employees(id), course_id BIGINT REFERENCES courses(id), assigned_by BIGINT REFERENCES users(id), status VARCHAR(40), assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE live_sessions (id BIGSERIAL PRIMARY KEY, course_id BIGINT REFERENCES courses(id), trainer_id BIGINT REFERENCES users(id), provider VARCHAR(40), meeting_url TEXT, starts_at TIMESTAMP, ends_at TIMESTAMP, status VARCHAR(32));
CREATE TABLE attendance (id BIGSERIAL PRIMARY KEY, live_session_id BIGINT REFERENCES live_sessions(id), user_id BIGINT REFERENCES users(id), attended_minutes INTEGER, attendance_percent NUMERIC(5,2));
CREATE TABLE notifications (id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES users(id), channel VARCHAR(24), title VARCHAR(255), body TEXT, read_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE messages (id BIGSERIAL PRIMARY KEY, sender_id BIGINT REFERENCES users(id), recipient_id BIGINT REFERENCES users(id), subject VARCHAR(255), body TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE resources (id BIGSERIAL PRIMARY KEY, title VARCHAR(255), resource_type VARCHAR(40), access_type VARCHAR(40), storage_key TEXT, description TEXT);
CREATE TABLE blogs (id BIGSERIAL PRIMARY KEY, title VARCHAR(255), slug VARCHAR(255) UNIQUE, body TEXT, seo_title VARCHAR(255), meta_description TEXT, published_at TIMESTAMP);
CREATE TABLE support_tickets (id BIGSERIAL PRIMARY KEY, ticket_no VARCHAR(120) UNIQUE, user_id BIGINT REFERENCES users(id), subject VARCHAR(255), category VARCHAR(80), priority VARCHAR(32), status VARCHAR(32), conversation TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES users(id), action VARCHAR(180), entity_type VARCHAR(80), entity_id VARCHAR(120), metadata TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE system_settings (id BIGSERIAL PRIMARY KEY, setting_key VARCHAR(180) UNIQUE, setting_value TEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
